import sys
sys.path.insert(0, '/work')
from solution import reserve
s={'a':5,'b':2}
assert reserve(s,[('a',2),('a',1)])=={'a':2,'b':2}
assert s=={'a':5,'b':2}
for req in [[('a',3),('a',3)],[('x',1)],[('a',0)],[('a',-1)]]:
    try: reserve(s,req)
    except ValueError: pass
    else: raise AssertionError('expected rejection')
assert s=={'a':5,'b':2}
assert reserve(s,[])==s

initial_files.solution.py:
from checks import available
def reserve(stock, requests):
    for sku, quantity in requests:
        if not available(stock, sku, quantity): raise ValueError('unavailable')
        stock[sku] -= quantity
    return stock

